SELECT p.first, p.last, c.START, p.birthdate, c.DESCRIPTION
FROM patients AS p JOIN conditions AS c ON c.PATIENT=p.patient
WHERE lower(c.DESCRIPTION) LIKE '%overdose%';

SELECT p.first, p.last, c.START, p.birthdate, c.DESCRIPTION
FROM patients p JOIN conditions c ON c.PATIENT=p.patient
