SELECT p.first, p.last, (julianday(c.START)-julianday(p.birthdate))/365.0 AS age
FROM patients p JOIN conditions c ON c.PATIENT=p.patient
WHERE c.DESCRIPTION='Drug overdose';

SELECT p.patient, p.prefix, p.first, p.last
