SELECT COUNT(CASE WHEN p.ethnicity = 'hispanic' AND substr(c.stop, 1, 4) = '2011' THEN c.patient END) * 1.0 / COUNT(c.patient) AS percentage
FROM careplans AS c
JOIN patients AS p ON c.patient = p.patient;

